'use strict';
const shoppingSelected=new Set();let shoppingSelectionContext='';
const purchaseHasHistory=s=>!!(s.purchase?.receipts?.length||s.purchase?.legacyReceived||s.purchase?.orderLog?.length||s.purchase?.receiptCorrections?.length);
function purchaseMoney(minor,currency){const n=BigInt(minor);return esc(currency)+' '+(n/100n).toLocaleString() +'.'+String(n%100n).padStart(2,'0');}
function purchasePriceFields(s){const p=s?.purchase?.price;return field('unitPrice','Unit price per item (optional)',p?(p.minor/100).toFixed(2):'')+field('currency','Currency (e.g. EUR)',p?.currency||'');}
function purchasePriceNote(s){return '<p class="tiny muted">'+(s.purchase?.price?purchaseMoney(s.purchase.price.minor,s.purchase.price.currency)+' per item':'Unit price not recorded')+'</p>';}
function purchaseOrderButtons(s){return (s.quantity-s.received-(s.purchase?.ordered||0)>0?btn('Mark ordered…','shop-order','small',s.id):'')+(s.purchase?.ordered?btn('Cancel order…','shop-cancel-order','small',s.id):'')+(purchaseHasHistory(s)?btn('History…','shop-history','small',s.id):'');}
function purchaseToolbar(info){
 const context=JSON.stringify([dataPath,db.id,shoppingFilters,viewOffset]);if(context!==shoppingSelectionContext){shoppingSelected.clear();shoppingSelectionContext=context;}
 const visible=new Set(db.planning.shopping.map(s=>s.id));for(const id of shoppingSelected)if(!visible.has(id))shoppingSelected.delete(id);
 const totals=info.totals;
 return `<div class="purchase-order-toolbar"><div class="actions">${btn('Select this page','shop-select-page','small')}${btn('Clear selection','shop-clear-selected','small ghost')}${btn(shoppingFilters.groupBySupplier?'Ungroup suppliers':'Group by supplier','shop-group-supplier','small')}<span id="shopping-selection-count" class="tiny">${shoppingSelected.size} selected on this page</span></div><div class="actions mt">${btn('Mark selected ordered…','shop-bulk-order')}${btn('Receive delivery…','shop-bulk-receive','primary')}${btn('Cancel selected orders…','shop-bulk-cancel')}</div><p class="tiny muted">Select purchases, then enter the quantity for each line. Deliveries add freely available stock; they do not reserve it for a build.</p>${totals?'<div class="purchase-costs">'+totals.currencies.map(t=>'<p><strong>'+esc(t.currency)+'</strong> · To buy '+purchaseMoney(t.toBuy,t.currency)+' · Ordered '+purchaseMoney(t.ordered,t.currency)+' · Received '+purchaseMoney(t.received,t.currency)+'</p>').join('')+'<p class="tiny muted">Estimates for all matching purchases at their current unit prices, excluding shipping and tax. '+totals.unknown+' item(s) without a price.</p></div>':''}</div>`;
}
function purchaseGroupedRows(lines){if(!shoppingFilters.groupBySupplier)return '<div class="purchase-grid">'+shoppingRows(lines)+'</div>';const groups=new Map();for(const s of lines){const key=s.supplier||'No supplier';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);}return [...groups].map(([name,rows])=>'<section class="purchase-supplier"><h2>'+esc(name)+'</h2><div class="purchase-grid">'+shoppingRows(rows)+'</div></section>').join('');}
function purchaseBatch(mode,ids){
 const lines=ids.map(id=>db.planning.shopping.find(s=>s.id===id));if(!lines.length)throw Error('Select purchases on this page first.');if(lines.some(s=>!s))throw Error('A selected purchase is no longer available. Refresh the page.');
 const limit=s=>mode==='order'?s.quantity-s.received-(s.purchase?.ordered||0):mode==='cancel'?s.purchase?.ordered||0:s.quantity-s.received;
 if(!lines.some(s=>limit(s)>0))throw Error('These purchases have no quantities available for this action.');
 if(mode==='receive'&&lines.some(s=>limit(s)>0&&s.purchase?.item.kind==='free'))throw Error('Choose a stock record for each free-text purchase before receiving a delivery.');
 const revision=db.revision,title=mode==='order'?'Record an order':mode==='cancel'?'Cancel outstanding orders':'Receive a delivery';
 modal(title,`<p>${mode==='order'?'Record an order you have already placed. This does not contact any supplier.':mode==='cancel'?'Cancel only the outstanding ordered quantities below. Received stock stays unchanged.':'Split this delivery between the selected purchases. Stock remains available to every build and workshop job.'} Enter zero to skip a line.</p><div class="table-wrap"><table><thead><tr><th>Purchase / source</th><th>Supplier</th><th>Quantity</th></tr></thead><tbody>${lines.map((s,i)=>'<tr><td><strong>'+esc(shoppingItem(s).name)+'</strong><br><span class="tiny muted">'+esc(shoppingLists().find(l=>l.id===s.purchase?.listId)?.name||'General shopping')+(s.buildName?' · '+esc(s.buildName):'')+(s.jobId?' · '+esc(db.jobs.find(j=>j.id===s.jobId)?.name||'Linked workshop job'):'')+'</span></td><td>'+esc(s.supplier||'Not specified')+'</td><td><input aria-label="Quantity for '+esc(shoppingItem(s).name)+'" name="quantity'+i+'" type="number" min="0" max="'+limit(s)+'" step="1" required value="'+(mode==='receive'?Math.min(limit(s),s.purchase?.ordered||limit(s)):limit(s))+'"></td></tr>').join('')}</tbody></table></div><label class="check-row mt"><input name="confirmed" type="checkbox" required>${mode==='receive'?'I have received these quantities and checked the split.':'I have checked these order quantities.'}</label>`,async v=>{
  const entries=lines.map((s,i)=>({id:s.id,quantity:Number(v['quantity'+i])})).filter(e=>e.quantity!==0);if(!entries.length)throw Error('Enter a quantity for at least one purchase.');
  const action=mode==='receive'?'planning.delivery.receive':mode==='cancel'?'planning.order.cancel':'planning.order.place';await change(action,{revision,entries,confirmed:!!v.confirmed});shoppingSelected.clear();await refreshJob();
 },mode==='receive'?'Receive into stock':mode==='cancel'?'Cancel order quantities':'Mark quantities ordered');
}
function purchaseHistory(id){
 const s=db.planning.shopping.find(s=>s.id===id);if(!s)throw Error('Purchase not found.');const p=s.purchase,c=p.receiptCorrections||[];
 const entries=[...(p.orderLog||[]).map(e=>({date:e.date,text:(e.type==='ordered'?'Ordered ':'Cancelled order: ')+e.quantity,details:e.supplier,price:e.price})),...p.receipts.map(r=>({date:r.receivedAt,text:'Received '+r.quantity+' ('+(r.quantity-c.filter(x=>x.receiptId===r.id).reduce((n,x)=>n+x.quantity,0))+' after corrections)',details:r.supplier||'',price:r.price})),...c.map(e=>({date:e.date,text:'Reversed '+e.quantity+' received · '+e.restoredOrdered+' returned to order',details:e.reason}))].sort((a,b)=>a.date.localeCompare(b.date));
 modal('Purchase history · '+shoppingItem(s).name,`${p.legacyReceived?'<p>'+p.legacyReceived+' received before individual receipts were recorded. No receipt date was recorded.</p>':''}${p.orderBaseline?'<p class="tiny muted">Opening order balance: '+p.orderBaseline+' (before detailed order logging).</p>':''}<div class="timeline">${entries.map(e=>'<article><strong>'+esc(e.text)+'</strong><p class="tiny muted">'+esc(new Date(e.date).toLocaleString())+'</p><p>'+esc(e.details)+(e.price?' · '+purchaseMoney(e.price.minor,e.price.currency)+' per item':'')+'</p></article>').join('')}</div>${p.receipts.some(r=>r.quantity>c.filter(x=>x.receiptId===r.id).reduce((n,x)=>n+x.quantity,0))?btn('Correct a receipt…','shop-correct','',id):''}<p class="plan-help">Corrections retain the original receipt. Only available stock can be reversed; fitted parts and assembly components are protected.</p>`,null);
 $('#dialog .dialog-footer [data-action=close-modal]').textContent='Close';
}
function purchaseCorrection(id){
 const s=db.planning.shopping.find(s=>s.id===id);if(!s)throw Error('Purchase not found.');const p=s.purchase,revision=db.revision;
 const receipts=p.receipts.map(r=>({...r,remaining:r.quantity-(p.receiptCorrections||[]).filter(c=>c.receiptId===r.id).reduce((n,c)=>n+c.quantity,0)})).filter(r=>r.remaining>0);
 modal('Correct receipt · '+shoppingItem(s).name,shoppingSelect('receiptId','Original receipt',receipts.map(r=>[r.id,new Date(r.receivedAt).toLocaleString()+' · '+r.remaining+' still received']),receipts[0]?.id,null)+field('quantity','Quantity to reverse',1,'number')+field('reason','Reason','','textarea')+'<label class="check-row"><input type="checkbox" name="restoreOrdered" checked>Return the originally ordered portion to outstanding orders</label><p>Available stock will decrease by the quantity entered. The original receipt stays in history.</p><label class="check-row"><input type="checkbox" name="confirmed" required>I have checked this stock correction.</label>',async v=>{await change('planning.receipt.correct',{revision,id,receiptId:v.receiptId,quantity:v.quantity,reason:v.reason,restoreOrdered:!!v.restoreOrdered,confirmed:!!v.confirmed});await refreshJob();},'Correct receipt');
 const q=$('#dialog [name=quantity]');q.min='1';q.step='1';q.required=true;$('#dialog [name=reason]').required=true;
}
async function shoppingOrderAction(action,id){
 if(action==='shop-select-page'){for(const s of db.planning.shopping)shoppingSelected.add(s.id);render();return true;}
 if(action==='shop-clear-selected'){shoppingSelected.clear();render();return true;}
 if(action==='shop-group-supplier'){shoppingFilters.groupBySupplier=!shoppingFilters.groupBySupplier;shoppingSelected.clear();render();return true;}
 const mode={'shop-order':'order','shop-cancel-order':'cancel','shop-bulk-order':'order','shop-bulk-cancel':'cancel','shop-bulk-receive':'receive'}[action];if(mode){purchaseBatch(mode,action.startsWith('shop-bulk-')?[...shoppingSelected]:[id]);return true;}
 if(action==='shop-history'){purchaseHistory(id);return true;}if(action==='shop-correct'){purchaseCorrection(id);return true;}return false;
}
document.addEventListener('change',e=>{if(!e.target.matches('[data-purchase-select]'))return;const id=e.target.dataset.purchaseSelect;if(e.target.checked)shoppingSelected.add(id);else shoppingSelected.delete(id);const label=$('#shopping-selection-count');if(label)label.textContent=shoppingSelected.size+' selected on this page';});
